%% Delayed TRN -> TC IPSP experiment
% This script asks whether TC neuron activity still decreases when the IPSP
% generated by the TRN neuron is delayed before it reaches the TC neuron.
%
% Two conditions are simulated with the same TC/TRN microcircuit parameters:
%   1. No-delay IPSP: TRN -> TC GABA_A/GABA_B arrives immediately.
%   2. Delayed IPSP: TRN -> TC GABA_A/GABA_B arrives after ipsp_delay_ms.
%
% The receptor kinetics, neurotransmitter pulse durations, reversal
% potentials, Mg2+ value, and GABA_B rate constants use the Destexhe values
% from the reference EPSC/IPSC script. Conductances are scaled for this
% two-cell conductance-based demonstration.

clear; close all; clc

%% Experiment controls
ipsp_delay_ms = 40; % delay from TRN release to TC IPSP arrival
activity_window_ms = 30; % pre/post window used for TC activity summary

params = delayed_ipsp_params();

no_delay = run_delayed_ipsp_condition(0, params);
delayed = run_delayed_ipsp_condition(ipsp_delay_ms, params);

no_delay_metrics = summarize_tc_activity(no_delay, activity_window_ms);
delayed_metrics = summarize_tc_activity(delayed, activity_window_ms);

%% Command-window summary
fprintf('Delayed TRN -> TC IPSP experiment\n');
fprintf('Configured IPSP delay: %.1f ms\n\n', ipsp_delay_ms);

print_condition_summary('No-delay IPSP', no_delay, no_delay_metrics);
print_condition_summary('Delayed IPSP', delayed, delayed_metrics);

%% Plot 1: TC and TRN voltage comparison
figure('Name', 'Delayed IPSP Experiment: Membrane Potentials', 'Color', 'w');

subplot(2, 1, 1)
plot(no_delay.time, no_delay.v_TC, 'Color', [0.75 0.75 0.75], ...
    'LineWidth', 1.1, 'DisplayName', 'TC, 0 ms IPSP delay')
hold on
plot(delayed.time, delayed.v_TC, 'r', 'LineWidth', 1.3, ...
    'DisplayName', sprintf('TC, %.0f ms IPSP delay', ipsp_delay_ms))
add_event_lines(delayed.TRN_release_times, 'k--', 'TRN release')
add_event_lines(delayed.TRN_ipsp_arrival_times, 'b:', 'Delayed IPSP arrival')
title('TC membrane potential with no-delay vs delayed TRN inhibition')
xlabel('Time (ms)')
ylabel('TC V_m (mV)')
legend('Location', 'best')
grid on

subplot(2, 1, 2)
plot(delayed.time, delayed.v_TRN, 'b', 'LineWidth', 1.2, 'DisplayName', 'TRN neuron')
hold on
stem(delayed.time(delayed.TRN_release_events == 1), ...
    45 * ones(1, sum(delayed.TRN_release_events)), ...
    'k', 'Marker', 'none', 'DisplayName', 'TRN release')
title('TRN membrane potential and release events')
xlabel('Time (ms)')
ylabel('TRN V_m (mV)')
legend('Location', 'best')
grid on

%% Plot 2: delayed IPSP currents and neurotransmitter pulses
figure('Name', 'Delayed IPSP Experiment: Inhibitory Currents', 'Color', 'w');

subplot(3, 1, 1)
plot(no_delay.time, no_delay.I_syn_TC, 'Color', [0.65 0.65 0.65], ...
    'LineWidth', 1.1, 'DisplayName', '0 ms IPSP delay')
hold on
plot(delayed.time, delayed.I_syn_TC, 'b', 'LineWidth', 1.3, ...
    'DisplayName', sprintf('%.0f ms IPSP delay', ipsp_delay_ms))
plot(delayed.time, zeros(size(delayed.time)), 'k:')
add_event_lines(delayed.TRN_release_times, 'k--', 'TRN release')
add_event_lines(delayed.TRN_ipsp_arrival_times, 'b:', 'Delayed IPSP arrival')
title('Total inhibitory current into TC')
xlabel('Time (ms)')
ylabel('Current')
legend('Location', 'best')
grid on

subplot(3, 1, 2)
plot(delayed.time, delayed.I_GABAa_TRN_TC, 'b', 'LineWidth', 1.2, ...
    'DisplayName', 'Delayed GABA_A')
hold on
plot(delayed.time, delayed.I_GABAb_TRN_TC, 'Color', [0.3 0.1 0.7], ...
    'LineWidth', 1.2, 'DisplayName', 'Delayed GABA_B')
plot(delayed.time, zeros(size(delayed.time)), 'k:')
title('Delayed IPSP components')
xlabel('Time (ms)')
ylabel('Current')
legend('Location', 'best')
grid on

subplot(3, 1, 3)
plot(delayed.time, delayed.nt_TRN_to_TC_GABAa, 'b', 'LineWidth', 1.1, ...
    'DisplayName', 'GABA_A pulse at TC')
hold on
plot(delayed.time, delayed.nt_TRN_to_TC_GABAb, 'Color', [0.3 0.1 0.7], ...
    'LineStyle', '--', 'LineWidth', 1.1, 'DisplayName', 'GABA_B pulse at TC')
stem(delayed.time(delayed.TRN_release_events == 1), ...
    1.2 * ones(1, sum(delayed.TRN_release_events)), ...
    'k', 'Marker', 'none', 'DisplayName', 'TRN generated IPSP')
title('TRN release and delayed GABA arrival at the TC cell')
xlabel('Time (ms)')
ylabel('[NT]')
ylim([-0.1 1.35])
legend('Location', 'best')
grid on

%% Plot 3: TC activity before and after IPSP arrival
figure('Name', 'Delayed IPSP Experiment: TC Activity Summary', 'Color', 'w');

subplot(2, 1, 1)
bar([no_delay_metrics.mean_v_before, no_delay_metrics.mean_v_after; ...
     delayed_metrics.mean_v_before, delayed_metrics.mean_v_after])
set(gca, 'XTickLabel', {'0 ms delay', sprintf('%.0f ms delay', ipsp_delay_ms)})
title(sprintf('Mean TC voltage %.0f ms before/after IPSP arrival', activity_window_ms))
ylabel('Mean TC V_m (mV)')
legend({'Before IPSP', 'After IPSP'}, 'Location', 'best')
grid on

subplot(2, 1, 2)
bar([no_delay_metrics.spikes_before, no_delay_metrics.spikes_after; ...
     delayed_metrics.spikes_before, delayed_metrics.spikes_after])
set(gca, 'XTickLabel', {'0 ms delay', sprintf('%.0f ms delay', ipsp_delay_ms)})
title(sprintf('TC spikes %.0f ms before/after IPSP arrival', activity_window_ms))
ylabel('Spike count')
legend({'Before IPSP', 'After IPSP'}, 'Location', 'best')
grid on

%% Plot 4: zoom around delayed IPSP arrivals
figure('Name', 'Delayed IPSP Experiment: Zoomed Delayed Responses', 'Color', 'w');

for event_idx = 1:numel(delayed.TRN_ipsp_arrival_times)
    arrival_time = delayed.TRN_ipsp_arrival_times(event_idx);
    zoom_mask = delayed.time >= arrival_time - activity_window_ms & ...
        delayed.time <= arrival_time + activity_window_ms;

    subplot(numel(delayed.TRN_ipsp_arrival_times), 1, event_idx)
    plot(delayed.time(zoom_mask), delayed.v_TC(zoom_mask), 'r', ...
        'LineWidth', 1.3, 'DisplayName', 'TC voltage')
    hold on
    yyaxis right
    plot(delayed.time(zoom_mask), delayed.I_syn_TC(zoom_mask), 'b', ...
        'LineWidth', 1.1, 'DisplayName', 'Delayed IPSP current')
    ylabel('Inhibitory current')
    yyaxis left
    add_event_lines(arrival_time, 'k:', 'IPSP arrival')
    title(sprintf('TC response around delayed IPSP arrival at %.0f ms', arrival_time))
    xlabel('Time (ms)')
    ylabel('TC V_m (mV)')
    grid on
end

%% Local functions
function params = delayed_ipsp_params()
    params.dt = 0.01; % ms
    params.t_end = 320; % ms
    params.spike_threshold = 0; % mV
    params.Cm = 1.0; % uF/cm^2

    % TC relay neuron
    params.gNa_TC = 120; params.ENa_TC = 50;
    params.gK_TC = 36; params.EK_TC = -77;
    params.gL_TC = 0.3; params.EL_TC = -54.4;

    % TRN neuron
    params.gNa_TRN = 100; params.ENa_TRN = 50;
    params.gK_TRN = 30; params.EK_TRN = -77;
    params.gL_TRN = 0.25; params.EL_TRN = -58;

    % Scheduled presynaptic events. TRN release is generated first; the
    % postsynaptic GABA pulse at TC is delayed inside each condition.
    params.TC_release_times = [25 175]; % ms, TC -> TRN excitation
    params.TRN_release_times = [90 220]; % ms, generated TRN -> TC IPSP

    % TC drive keeps the TC cell active near the IPSP windows so a drop in
    % activity can be seen when inhibition arrives.
    params.TC_drive_windows = [20 38 10; 65 155 6.8; 170 188 8; 205 295 6.4];
    params.TRN_drive_windows = [82 102 8; 212 232 8];

    % TC -> TRN excitation
    params.Cmax_AMPA = 1;
    params.Cdur_AMPA = 1;
    params.alpha_AMPA = 1.1;
    params.beta_AMPA = 0.19;
    params.E_AMPA = 0;
    params.g_AMPA_TC_TRN = 0.18;

    params.Cmax_NMDA = 1;
    params.Cdur_NMDA = 1;
    params.alpha_NMDA = 0.072;
    params.beta_NMDA = 0.0066;
    params.E_NMDA = 0;
    params.g_NMDA_TC_TRN = 0.12;
    params.mg_NMDA = 1;

    % TRN -> TC inhibition
    params.Cmax_GABAa = 1;
    params.Cdur_GABAa = 1;
    params.alpha_GABAa = 5;
    params.beta_GABAa = 0.18;
    params.E_GABAa = -80;
    params.g_GABAa_TRN_TC = 0.20;

    params.Cmax_GABAb = 1;
    params.Cdur_GABAb = 1;
    params.K1_GABAb = 0.09;
    params.K2_GABAb = 0.0012;
    params.K3_GABAb = 0.18;
    params.K4_GABAb = 0.034;
    params.KD_GABAb = 0.08;
    params.n_GABAb = 4;
    params.E_GABAb = -95;
    params.g_GABAb_TRN_TC = 0.04;
end

function sim = run_delayed_ipsp_condition(ipsp_delay_ms, params)
    dt = params.dt;
    time = 0:dt:params.t_end;
    nt = numel(time);

    I_ext_TC = zeros(1, nt);
    I_ext_TRN = zeros(1, nt);

    for row = 1:size(params.TC_drive_windows, 1)
        start_t = params.TC_drive_windows(row, 1);
        stop_t = params.TC_drive_windows(row, 2);
        amp = params.TC_drive_windows(row, 3);
        I_ext_TC(time >= start_t & time < stop_t) = amp;
    end

    for row = 1:size(params.TRN_drive_windows, 1)
        start_t = params.TRN_drive_windows(row, 1);
        stop_t = params.TRN_drive_windows(row, 2);
        amp = params.TRN_drive_windows(row, 3);
        I_ext_TRN(time >= start_t & time < stop_t) = amp;
    end

    v_TC = -65 * ones(1, nt);
    v_TRN = -65 * ones(1, nt);
    m_TC = zeros(1, nt); h_TC = zeros(1, nt); n_TC = zeros(1, nt);
    m_TRN = zeros(1, nt); h_TRN = zeros(1, nt); n_TRN = zeros(1, nt);

    [m_TC(1), h_TC(1), n_TC(1)] = init_hh_gates(v_TC(1));
    [m_TRN(1), h_TRN(1), n_TRN(1)] = init_hh_gates(v_TRN(1));

    nt_TC_to_TRN_AMPA = zeros(1, nt);
    nt_TC_to_TRN_NMDA = zeros(1, nt);
    nt_TRN_to_TC_GABAa = zeros(1, nt);
    nt_TRN_to_TC_GABAb = zeros(1, nt);

    r_AMPA_TRN = zeros(1, nt);
    r_NMDA_TRN = zeros(1, nt);
    B_NMDA_TRN = zeros(1, nt);
    r_GABAa_TC = zeros(1, nt);
    r_GABAb_TC = zeros(1, nt);
    G_GABAb_TC = zeros(1, nt);
    GABAb_open_TC = zeros(1, nt);

    I_AMPA_TC_TRN = zeros(1, nt);
    I_NMDA_TC_TRN = zeros(1, nt);
    I_GABAa_TRN_TC = zeros(1, nt);
    I_GABAb_TRN_TC = zeros(1, nt);
    I_syn_TRN = zeros(1, nt);
    I_syn_TC = zeros(1, nt);

    TC_spike_events = zeros(1, nt);
    TRN_spike_events = zeros(1, nt);
    TC_release_events = event_vector(time, params.TC_release_times);
    TRN_release_events = event_vector(time, params.TRN_release_times);
    TRN_ipsp_arrival_times = params.TRN_release_times + ipsp_delay_ms;
    TRN_ipsp_arrival_events = event_vector(time, TRN_ipsp_arrival_times);

    tc_release_AMPA_steps = 0;
    tc_release_NMDA_steps = 0;
    trn_release_GABAa_steps = 0;
    trn_release_GABAb_steps = 0;

    AMPA_pulse_steps = max(1, round(params.Cdur_AMPA / dt));
    NMDA_pulse_steps = max(1, round(params.Cdur_NMDA / dt));
    GABAa_pulse_steps = max(1, round(params.Cdur_GABAa / dt));
    GABAb_pulse_steps = max(1, round(params.Cdur_GABAb / dt));

    for k = 1:nt-1
        TC_spike = k > 1 && v_TC(k-1) < params.spike_threshold && ...
            v_TC(k) >= params.spike_threshold;
        TRN_spike = k > 1 && v_TRN(k-1) < params.spike_threshold && ...
            v_TRN(k) >= params.spike_threshold;

        if TC_spike
            TC_spike_events(k) = 1;
        end

        if TRN_spike
            TRN_spike_events(k) = 1;
        end

        if TC_release_events(k) == 1
            tc_release_AMPA_steps = AMPA_pulse_steps;
            tc_release_NMDA_steps = NMDA_pulse_steps;
        end

        if TRN_ipsp_arrival_events(k) == 1
            trn_release_GABAa_steps = GABAa_pulse_steps;
            trn_release_GABAb_steps = GABAb_pulse_steps;
        end

        if tc_release_AMPA_steps > 0
            nt_TC_to_TRN_AMPA(k) = params.Cmax_AMPA;
            tc_release_AMPA_steps = tc_release_AMPA_steps - 1;
        end

        if tc_release_NMDA_steps > 0
            nt_TC_to_TRN_NMDA(k) = params.Cmax_NMDA;
            tc_release_NMDA_steps = tc_release_NMDA_steps - 1;
        end

        if trn_release_GABAa_steps > 0
            nt_TRN_to_TC_GABAa(k) = params.Cmax_GABAa;
            trn_release_GABAa_steps = trn_release_GABAa_steps - 1;
        end

        if trn_release_GABAb_steps > 0
            nt_TRN_to_TC_GABAb(k) = params.Cmax_GABAb;
            trn_release_GABAb_steps = trn_release_GABAb_steps - 1;
        end

        dAMPA_rdt = params.alpha_AMPA * nt_TC_to_TRN_AMPA(k) * ...
            (1 - r_AMPA_TRN(k)) - params.beta_AMPA * r_AMPA_TRN(k);
        r_AMPA_TRN(k+1) = clamp01(r_AMPA_TRN(k) + dt * dAMPA_rdt);

        dNMDA_rdt = params.alpha_NMDA * nt_TC_to_TRN_NMDA(k) * ...
            (1 - r_NMDA_TRN(k)) - params.beta_NMDA * r_NMDA_TRN(k);
        r_NMDA_TRN(k+1) = clamp01(r_NMDA_TRN(k) + dt * dNMDA_rdt);
        B_NMDA_TRN(k) = magnesium_block(v_TRN(k), params.mg_NMDA);

        dGABAa_rdt = params.alpha_GABAa * nt_TRN_to_TC_GABAa(k) * ...
            (1 - r_GABAa_TC(k)) - params.beta_GABAa * r_GABAa_TC(k);
        r_GABAa_TC(k+1) = clamp01(r_GABAa_TC(k) + dt * dGABAa_rdt);

        dGABAb_rdt = params.K1_GABAb * nt_TRN_to_TC_GABAb(k) * ...
            (1 - r_GABAb_TC(k)) - params.K2_GABAb * r_GABAb_TC(k);
        r_GABAb_TC(k+1) = clamp01(r_GABAb_TC(k) + dt * dGABAb_rdt);

        dGABAb_Gdt = params.K3_GABAb * r_GABAb_TC(k) - ...
            params.K4_GABAb * G_GABAb_TC(k);
        G_GABAb_TC(k+1) = max(G_GABAb_TC(k) + dt * dGABAb_Gdt, 0);
        GABAb_open_TC(k) = gprotein_channel_open(G_GABAb_TC(k), ...
            params.n_GABAb, params.KD_GABAb);

        I_AMPA_TC_TRN(k) = params.g_AMPA_TC_TRN * r_AMPA_TRN(k) * ...
            (params.E_AMPA - v_TRN(k));
        I_NMDA_TC_TRN(k) = params.g_NMDA_TC_TRN * B_NMDA_TRN(k) * ...
            r_NMDA_TRN(k) * (params.E_NMDA - v_TRN(k));
        I_GABAa_TRN_TC(k) = params.g_GABAa_TRN_TC * r_GABAa_TC(k) * ...
            (params.E_GABAa - v_TC(k));
        I_GABAb_TRN_TC(k) = params.g_GABAb_TRN_TC * GABAb_open_TC(k) * ...
            (params.E_GABAb - v_TC(k));

        I_syn_TRN(k) = I_AMPA_TC_TRN(k) + I_NMDA_TC_TRN(k);
        I_syn_TC(k) = I_GABAa_TRN_TC(k) + I_GABAb_TRN_TC(k);

        [am, bm, ah, bh, an, bn] = hh_rates(v_TC(k));
        m_TC(k+1) = clamp01(m_TC(k) + dt * (am * (1 - m_TC(k)) - bm * m_TC(k)));
        h_TC(k+1) = clamp01(h_TC(k) + dt * (ah * (1 - h_TC(k)) - bh * h_TC(k)));
        n_TC(k+1) = clamp01(n_TC(k) + dt * (an * (1 - n_TC(k)) - bn * n_TC(k)));

        [am, bm, ah, bh, an, bn] = hh_rates(v_TRN(k));
        m_TRN(k+1) = clamp01(m_TRN(k) + dt * (am * (1 - m_TRN(k)) - bm * m_TRN(k)));
        h_TRN(k+1) = clamp01(h_TRN(k) + dt * (ah * (1 - h_TRN(k)) - bh * h_TRN(k)));
        n_TRN(k+1) = clamp01(n_TRN(k) + dt * (an * (1 - n_TRN(k)) - bn * n_TRN(k)));

        INa_TC = params.gNa_TC * m_TC(k)^3 * h_TC(k) * (v_TC(k) - params.ENa_TC);
        IK_TC = params.gK_TC * n_TC(k)^4 * (v_TC(k) - params.EK_TC);
        IL_TC = params.gL_TC * (v_TC(k) - params.EL_TC);

        INa_TRN = params.gNa_TRN * m_TRN(k)^3 * h_TRN(k) * ...
            (v_TRN(k) - params.ENa_TRN);
        IK_TRN = params.gK_TRN * n_TRN(k)^4 * (v_TRN(k) - params.EK_TRN);
        IL_TRN = params.gL_TRN * (v_TRN(k) - params.EL_TRN);

        dv_TC = (I_ext_TC(k) + I_syn_TC(k) - INa_TC - IK_TC - IL_TC) / params.Cm;
        dv_TRN = (I_ext_TRN(k) + I_syn_TRN(k) - INa_TRN - IK_TRN - IL_TRN) / params.Cm;

        v_TC(k+1) = v_TC(k) + dt * dv_TC;
        v_TRN(k+1) = v_TRN(k) + dt * dv_TRN;
    end

    B_NMDA_TRN(end) = magnesium_block(v_TRN(end), params.mg_NMDA);
    GABAb_open_TC(end) = gprotein_channel_open(G_GABAb_TC(end), ...
        params.n_GABAb, params.KD_GABAb);
    I_AMPA_TC_TRN(end) = params.g_AMPA_TC_TRN * r_AMPA_TRN(end) * ...
        (params.E_AMPA - v_TRN(end));
    I_NMDA_TC_TRN(end) = params.g_NMDA_TC_TRN * B_NMDA_TRN(end) * ...
        r_NMDA_TRN(end) * (params.E_NMDA - v_TRN(end));
    I_GABAa_TRN_TC(end) = params.g_GABAa_TRN_TC * r_GABAa_TC(end) * ...
        (params.E_GABAa - v_TC(end));
    I_GABAb_TRN_TC(end) = params.g_GABAb_TRN_TC * GABAb_open_TC(end) * ...
        (params.E_GABAb - v_TC(end));
    I_syn_TRN(end) = I_AMPA_TC_TRN(end) + I_NMDA_TC_TRN(end);
    I_syn_TC(end) = I_GABAa_TRN_TC(end) + I_GABAb_TRN_TC(end);

    sim.delay_ms = ipsp_delay_ms;
    sim.time = time;
    sim.I_ext_TC = I_ext_TC;
    sim.I_ext_TRN = I_ext_TRN;
    sim.v_TC = v_TC;
    sim.v_TRN = v_TRN;
    sim.nt_TC_to_TRN_AMPA = nt_TC_to_TRN_AMPA;
    sim.nt_TC_to_TRN_NMDA = nt_TC_to_TRN_NMDA;
    sim.nt_TRN_to_TC_GABAa = nt_TRN_to_TC_GABAa;
    sim.nt_TRN_to_TC_GABAb = nt_TRN_to_TC_GABAb;
    sim.I_AMPA_TC_TRN = I_AMPA_TC_TRN;
    sim.I_NMDA_TC_TRN = I_NMDA_TC_TRN;
    sim.I_GABAa_TRN_TC = I_GABAa_TRN_TC;
    sim.I_GABAb_TRN_TC = I_GABAb_TRN_TC;
    sim.I_syn_TRN = I_syn_TRN;
    sim.I_syn_TC = I_syn_TC;
    sim.TC_spike_events = TC_spike_events;
    sim.TRN_spike_events = TRN_spike_events;
    sim.TC_release_events = TC_release_events;
    sim.TRN_release_events = TRN_release_events;
    sim.TRN_ipsp_arrival_events = TRN_ipsp_arrival_events;
    sim.TC_release_times = params.TC_release_times;
    sim.TRN_release_times = params.TRN_release_times;
    sim.TRN_ipsp_arrival_times = TRN_ipsp_arrival_times;
end

function metrics = summarize_tc_activity(sim, window_ms)
    before_spikes = 0;
    after_spikes = 0;
    before_v = [];
    after_v = [];

    for arrival_time = sim.TRN_ipsp_arrival_times
        before_mask = sim.time >= arrival_time - window_ms & sim.time < arrival_time;
        after_mask = sim.time >= arrival_time & sim.time < arrival_time + window_ms;

        before_v = [before_v, sim.v_TC(before_mask)]; %#ok<AGROW>
        after_v = [after_v, sim.v_TC(after_mask)]; %#ok<AGROW>
        before_spikes = before_spikes + sum(sim.TC_spike_events(before_mask));
        after_spikes = after_spikes + sum(sim.TC_spike_events(after_mask));
    end

    metrics.mean_v_before = mean(before_v);
    metrics.mean_v_after = mean(after_v);
    metrics.delta_mean_v = metrics.mean_v_after - metrics.mean_v_before;
    metrics.spikes_before = before_spikes;
    metrics.spikes_after = after_spikes;
    metrics.delta_spikes = after_spikes - before_spikes;
end

function print_condition_summary(label, sim, metrics)
    fprintf('%s\n', label);
    fprintf('  TRN generated IPSP times: %s ms\n', mat2str(sim.TRN_release_times));
    fprintf('  TC IPSP arrival times:    %s ms\n', mat2str(sim.TRN_ipsp_arrival_times));
    fprintf('  TC spikes total:          %d\n', sum(sim.TC_spike_events));
    fprintf('  TRN spikes total:         %d\n', sum(sim.TRN_spike_events));
    fprintf('  Mean TC V_m before IPSP:  %.2f mV\n', metrics.mean_v_before);
    fprintf('  Mean TC V_m after IPSP:   %.2f mV\n', metrics.mean_v_after);
    fprintf('  After-before TC V_m:      %.2f mV\n', metrics.delta_mean_v);
    fprintf('  TC spikes before/after:   %d / %d\n\n', ...
        metrics.spikes_before, metrics.spikes_after);
end

function events = event_vector(time, event_times)
    events = zeros(size(time));

    for event_time = event_times
        if event_time >= time(1) && event_time <= time(end)
            [~, event_idx] = min(abs(time - event_time));
            events(event_idx) = 1;
        end
    end
end

function add_event_lines(event_times, style, label_text)
    ax = gca;
    y_limits = ylim(ax);
    label_used = false;

    for event_time = event_times
        if label_used
            plot([event_time event_time], y_limits, style, ...
                'HandleVisibility', 'off')
        else
            plot([event_time event_time], y_limits, style, ...
                'DisplayName', label_text)
            label_used = true;
        end
    end

    ylim(ax, y_limits)
end

function [m0, h0, n0] = init_hh_gates(V)
    [am, bm, ah, bh, an, bn] = hh_rates(V);
    m0 = am / (am + bm);
    h0 = ah / (ah + bh);
    n0 = an / (an + bn);
end

function [am, bm, ah, bh, an, bn] = hh_rates(V)
    am = alpha_m(V); bm = beta_m(V);
    ah = alpha_h(V); bh = beta_h(V);
    an = alpha_n(V); bn = beta_n(V);
end

function val = alpha_m(V)
    x = V + 40;
    if abs(x) < 1e-6
        val = 1.0;
    else
        val = 0.1 * x / (1 - exp(-x / 10));
    end
end

function val = beta_m(V)
    val = 4 * exp(-(V + 65) / 18);
end

function val = alpha_h(V)
    val = 0.07 * exp(-(V + 65) / 20);
end

function val = beta_h(V)
    val = 1 / (1 + exp(-(V + 35) / 10));
end

function val = alpha_n(V)
    x = V + 55;
    if abs(x) < 1e-6
        val = 0.1;
    else
        val = 0.01 * x / (1 - exp(-x / 10));
    end
end

function val = beta_n(V)
    val = 0.125 * exp(-(V + 65) / 80);
end

function val = clamp01(x)
    val = min(max(x, 0), 1);
end

function val = magnesium_block(V, mg)
    val = 1 / (1 + exp(0.062 * (-V)) * (mg / 3.57));
end

function val = gprotein_channel_open(G, n_sites, KD)
    val = (G^n_sites) / (G^n_sites + KD);
end
